from collections import deque, OrderedDict
from functools import lru_cache
from array import array

EMPTY = ("empty",)
EPS = ("eps",)
DOT = ("dot",)


def make_lit(ch: str, alphabet: str) -> object:
    if ch in alphabet:
        return ("lit", ch)
    return EMPTY


def make_class(allowed: set, alphabet: str) -> object:
    allowed &= set(alphabet)
    if not allowed:
        return EMPTY
    if len(allowed) == len(alphabet):
        return DOT
    if len(allowed) == 1:
        return ("lit", next(iter(allowed)))
    return ("class", frozenset(allowed))


def make_seq(parts):
    flat = []
    for p in parts:
        if p is EMPTY:
            return EMPTY
        if p is EPS:
            continue
        if isinstance(p, tuple) and p[0] == "seq":
            flat.extend(p[1])
        else:
            flat.append(p)
    if not flat:
        return EPS
    if len(flat) == 1:
        return flat[0]
    return ("seq", tuple(flat))


def make_union(branches):
    flat = []
    seen = set()
    for b in branches:
        if b is EMPTY:
            continue
        if isinstance(b, tuple) and b[0] == "alt":
            for x in b[1]:
                if x not in seen:
                    seen.add(x)
                    flat.append(x)
        else:
            if b not in seen:
                seen.add(b)
                flat.append(b)
    if not flat:
        return EMPTY
    if len(flat) == 1:
        return flat[0]
    return ("alt", tuple(flat))


def make_star(r):
    if r is EMPTY or r is EPS:
        return EPS
    if isinstance(r, tuple) and r[0] == "star":
        return r
    return ("star", r)


def make_plus(r):
    if r is EMPTY:
        return EMPTY
    if r is EPS:
        return EPS
    if isinstance(r, tuple) and r[0] == "star":
        return r
    if isinstance(r, tuple) and r[0] == "plus":
        return r
    return ("plus", r)


def make_maybe(r):
    if r is EMPTY:
        return EPS
    if r is EPS:
        return EPS
    return make_union((EPS, r))


@lru_cache(maxsize=None)
def nullable(r: object) -> bool:
    if r is EMPTY:
        return False
    if r is EPS:
        return True
    kind = r[0]
    if kind == "lit" or kind == "dot" or kind == "class":
        return False
    if kind == "seq":
        for x in r[1]:
            if not nullable(x):
                return False
        return True
    if kind == "alt":
        return any(nullable(x) for x in r[1])
    if kind == "star":
        return True
    if kind == "plus":
        return nullable(r[1])
    raise AssertionError


def is_empty(r: object) -> bool:
    return r is EMPTY


def derive(r: object, ch: str, alphabet: str):
    if r is EMPTY:
        return EMPTY
    if r is EPS:
        return EMPTY

    kind = r[0]

    if kind == "lit":
        return EPS if r[1] == ch else EMPTY

    if kind == "dot":
        return EPS

    if kind == "class":
        return EPS if ch in r[1] else EMPTY

    if kind == "alt":
        return make_union(derive(x, ch, alphabet) for x in r[1])

    if kind == "seq":
        parts = r[1]
        branches = []
        for i, part in enumerate(parts):
            d = derive(part, ch, alphabet)
            if not is_empty(d):
                if i + 1 < len(parts):
                    branches.append(make_seq((d, *parts[i + 1 :])))
                else:
                    branches.append(d)
            if not nullable(part):
                break
        return make_union(branches)

    if kind == "star":
        inner = r[1]
        d = derive(inner, ch, alphabet)
        if is_empty(d):
            return EMPTY
        return make_seq((d, make_star(inner)))

    if kind == "plus":
        inner = r[1]
        d = derive(inner, ch, alphabet)
        if is_empty(d):
            return EMPTY
        return make_seq((d, make_star(inner)))

    raise AssertionError


def parse_pattern(pattern: str, alphabet: str):
    alpha_set = set(alphabet)

    def parse_alt():
        nonlocal pos
        branches = [parse_concat()]
        while pos < len(pattern) and pattern[pos] == "|":
            pos += 1
            branches.append(parse_concat())
        return make_union(branches)

    def parse_concat():
        nonlocal pos
        parts = []
        while pos < len(pattern):
            ch = pattern[pos]
            if ch == "|" or ch == ")":
                break
            if ch in "*+?":
                raise ValueError
            elem = parse_element()
            if pos < len(pattern) and pattern[pos] in "*+?":
                q = pattern[pos]
                pos += 1
                if q == "*":
                    elem = make_star(elem)
                elif q == "+":
                    elem = make_plus(elem)
                else:
                    elem = make_maybe(elem)
            parts.append(elem)
        return make_seq(parts)

    def parse_element():
        nonlocal pos
        if pos >= len(pattern):
            return EPS

        ch = pattern[pos]

        if ch == "(":
            pos += 1
            inner = parse_alt()
            if pos >= len(pattern) or pattern[pos] != ")":
                raise ValueError
            pos += 1
            return inner

        if ch == ")":
            raise ValueError

        if ch == "\\":
            pos += 1
            if pos >= len(pattern):
                raise ValueError
            c = pattern[pos]
            pos += 1
            return make_lit(c, alphabet)

        if ch == ".":
            pos += 1
            return DOT

        if ch == "[":
            return parse_class()

        pos += 1
        return make_lit(ch, alphabet)

    def parse_class():
        nonlocal pos
        pos += 1  # consume [
        neg = False
        if pos < len(pattern) and pattern[pos] == "^":
            neg = True
            pos += 1

        listed = set()
        items = 0

        while pos < len(pattern):
            if pattern[pos] == "]":
                pos += 1
                break

            # first endpoint of item/range
            if pattern[pos] == "\\":
                pos += 1
                if pos >= len(pattern):
                    raise ValueError
                first = pattern[pos]
                pos += 1
            else:
                first = pattern[pos]
                pos += 1

            if (
                pos + 1 < len(pattern)
                and pattern[pos] == "-"
                and pattern[pos + 1] != "]"
            ):
                pos += 1  # consume -
                if pattern[pos] == "\\":
                    pos += 1
                    if pos >= len(pattern):
                        raise ValueError
                    second = pattern[pos]
                    pos += 1
                else:
                    second = pattern[pos]
                    pos += 1

                if ord(first) > ord(second):
                    raise ValueError

                for c in alpha_set:
                    if ord(first) <= ord(c) <= ord(second):
                        listed.add(c)
                items += 1
            else:
                listed.add(first)
                items += 1
        else:
            raise ValueError

        if items == 0:
            raise ValueError

        allowed = set(alphabet) if neg else set()
        if neg:
            allowed -= listed
        else:
            allowed = listed

        return make_class(allowed, alphabet)

    pos = 0
    result = parse_alt()
    if pos != len(pattern):
        raise ValueError
    return result


def build_dfa(start_ast: object, alphabet: str):
    m = len(alphabet)
    state_ast = [start_ast]
    trans = []
    accept = []
    ast_index = {start_ast: 0}

    def get_index(r):
        nonlocal trans, accept, ast_index
        if r in ast_index:
            return ast_index[r]
        idx = len(state_ast)
        state_ast.append(r)
        ast_index[r] = idx
        accept.append(nullable(r))
        trans.append(None)  # placeholder, filled when processed
        return idx

    q = deque([0])
    while q:
        i = q.popleft()
        r = state_ast[i]
        if r is EMPTY:
            row = tuple([get_index(EMPTY) for _ in range(m)])
        else:
            row = tuple([get_index(derive(r, c, alphabet)) for c in alphabet])
        trans[i] = row

    return len(state_ast), trans, accept, 0


def minimize_dfa(n: int, m: int, trans, accept):
    if n == 0:
        return 0, [], [False]

    all_mask = (1 << n) - 1
    acc_mask = 0
    for i, a in enumerate(accept):
        if a:
            acc_mask |= 1 << i

    blocks = []
    if acc_mask == 0:
        blocks = [all_mask]
    elif acc_mask == all_mask:
        blocks = [all_mask]
    else:
        blocks = [acc_mask, all_mask ^ acc_mask]

    block_id = [0] * n
    for i in range(n):
        if acc_mask:
            block_id[i] = 1 if ((acc_mask >> i) & 1) == 0 else 0

    pred_bits = [[0] * n for _ in range(m)]
    for src, row in enumerate(trans):
        for c, dst in enumerate(row):
            pred_bits[c][dst] |= 1 << src

    w = deque()
    in_queue = [False] * len(blocks)
    for bi in range(len(blocks)):
        if blocks[bi]:
            w.append(bi)
            in_queue[bi] = True

    while w:
        bi = w.popleft()
        in_queue[bi] = False
        pbits = blocks[bi]
        if pbits == 0:
            continue

        for c in range(m):
            pre = 0
            x = pbits
            pb = pred_bits[c]
            while x:
                lsb = x & -x
                q = lsb.bit_length() - 1
                pre |= pb[q]
                x ^= lsb

            if pre == 0 or pre == all_mask:
                continue

            groups = {}
            y = pre
            while y:
                bit = y & -y
                p = bit.bit_length() - 1
                b = block_id[p]
                groups[b] = groups.get(b, 0) | bit
                y ^= bit

            for b, part in groups.items():
                block = blocks[b]
                if part == block:
                    continue
                comp = block ^ part
                if comp == 0:
                    continue

                if part.bit_count() <= comp.bit_count():
                    blocks[b] = comp
                    new_id = len(blocks)
                    blocks.append(part)
                    in_queue.append(False)

                    z = part
                    while z:
                        bit = z & -z
                        p = bit.bit_length() - 1
                        block_id[p] = new_id
                        z ^= bit
                else:
                    blocks[b] = part
                    new_id = len(blocks)
                    blocks.append(comp)
                    in_queue.append(False)

                    z = comp
                    while z:
                        bit = z & -z
                        p = bit.bit_length() - 1
                        block_id[p] = new_id
                        z ^= bit

                if not in_queue[b]:
                    w.append(b)
                    in_queue[b] = True
                if not in_queue[new_id]:
                    w.append(new_id)
                    in_queue[new_id] = True

    qn = len(blocks)
    q_trans = [[0] * m for _ in range(qn)]
    q_accept = [False] * qn

    for bi in range(qn):
        bits = blocks[bi]
        if bits == 0:
            continue
        rep = (bits & -bits).bit_length() - 1
        q_accept[bi] = accept[rep]
        for c in range(m):
            q_trans[bi][c] = block_id[trans[rep][c]]

    reachable = []
    seen = [False] * qn
    start_b = 0
    for i in range(n):
        if trans[i] and seen[i] is False:
            pass
    # In this construction state 0 is reachable; after minimization start remains 0
    start_b = 0

    # Keep only quotient states reachable from start_b (should already be all)
    order = [start_b]
    seen = [False] * qn
    seen[start_b] = True
    for x in order:
        for t in q_trans[x]:
            if not seen[t]:
                seen[t] = True
                order.append(t)

    remap = [-1] * qn
    for i, x in enumerate(order):
        remap[x] = i

    final_trans = []
    final_accept = []
    for x in order:
        final_trans.append([remap[y] for y in q_trans[x]])
        final_accept.append(q_accept[x])

    return len(order), final_trans, final_accept


def canonical_dfa(n: int, trans, accept, alphabet: str):
    m = len(alphabet)
    order = [0]
    seen = [False] * n
    seen[0] = True
    for x in order:
        for t in trans[x]:
            if not seen[t]:
                seen[t] = True
                order.append(t)

    remap = [-1] * n
    for i, x in enumerate(order):
        remap[x] = i

    acc_new = tuple(accept[x] for x in order)
    trans_new = tuple(tuple(remap[y] for y in trans[x]) for x in order)
    return acc_new, trans_new


def distinguish_strings(dfa1, dfa2, alphabet: str):
    n1, t1, a1 = dfa1
    n2, t2, a2 = dfa2
    m = len(alphabet)

    if a1[0] != a2[0]:
        return ""

    total = n1 * n2
    start = 0

    # Use compact arrays for product visited/parent when reasonably sized.
    if total <= 12_000_000:
        parent = array("i", [-2]) * total
        pchar = array("b", [-1]) * total
        parent[start] = -1
        q = deque([start])

        while q:
            k = q.popleft()
            x = k // n2
            y = k - x * n2
            for c in range(m):
                nx = t1[x][c]
                ny = t2[y][c]
                if a1[nx] != a2[ny]:
                    ans = []
                    ans.append(alphabet[c])
                    pk = k
                    pc = c
                    while pk != -1:
                        ans.append(alphabet[pc])
                        nk = pk
                        pk = parent[nk]
                        pc = pchar[nk]
                    ans.reverse()
                    return "".join(ans)

                nk = nx * n2 + ny
                if parent[nk] == -2:
                    parent[nk] = k
                    pchar[nk] = c
                    q.append(nk)

        return None

    # Fallback for very large products: dict-based BFS.
    parent = {start: (-1, -1)}
    q = deque([start])
    while q:
        k = q.popleft()
        x = k // n2
        y = k - x * n2
        for c in range(m):
            nx = t1[x][c]
            ny = t2[y][c]
            if a1[nx] != a2[ny]:
                ans = [alphabet[c]]
                pk = k
                pc = c
                while pk != -1:
                    ans.append(alphabet[pc])
                    nk = pk
                    pk = parent[nk][0]
                    pc = parent[nk][1]
                ans.reverse()
                return "".join(ans)
            nk = nx * n2 + ny
            if nk not in parent:
                parent[nk] = (k, c)
                q.append(nk)

    return None


def min_dfa_size(pattern: str, alphabet: str) -> int:
    if not alphabet:
        raise ValueError
    if len(set(alphabet)) != len(alphabet):
        raise ValueError

    ast = parse_pattern(pattern, alphabet)
    n, trans, accept, _ = build_dfa(ast, alphabet)
    qn, qt, qa = minimize_dfa(n, len(alphabet), trans, accept)
    return qn


def distinguish(p1: str, p2: str, alphabet: str) -> str | None:
    if not alphabet:
        raise ValueError
    if len(set(alphabet)) != len(alphabet):
        raise ValueError

    ast1 = parse_pattern(p1, alphabet)
    ast2 = parse_pattern(p2, alphabet)

    n1, t1, a1, _ = build_dfa(ast1, alphabet)
    n1, t1, a1 = minimize_dfa(n1, len(alphabet), t1, a1)

    n2, t2, a2, _ = build_dfa(ast2, alphabet)
    n2, t2, a2 = minimize_dfa(n2, len(alphabet), t2, a2)

    c1 = canonical_dfa(n1, t1, a1, alphabet)
    c2 = canonical_dfa(n2, t2, a2, alphabet)
    if c1 == c2:
        return None

    return distinguish_strings((n1, t1, a1), (n2, t2, a2), alphabet)
